addEventListener('keydown',e=>{ if(e.key==='Escape') show('home'); });

/* ===== عرض الحالة الحالية ===== */
function setNow(name,desc){
  $('#nowName').textContent=name; $('#nowDesc').textContent=desc; $('#miniName').textContent=name;
}
function setUI(state){ // 'idle' | 'loading' | 'playing'
  const playing = state==='playing';
  $('#app').classList.toggle('playing',playing);
  const d = playing?PAUSE:PLAY;
  $('#bigIcon').setAttribute('d',d); $('#miniIcon').setAttribute('d',d);
  $('#bigText').textContent = state==='loading'?'جارٍ التحميل…':playing?'إيقاف مؤقت':'استمع الآن';
  $('#bigPlay').classList.toggle('loading',state==='loading');
  const lbl = playing?'يُبثّ الآن':'المحطة الحالية';
  $('#nowLabel').textContent=lbl; $('#miniLabel').textContent=lbl;
  $('#pillText').textContent = playing?'بث مباشر':state==='loading'?'جارٍ الاتصال':'جاهز';
}

/* ===== تشغيل ===== */
