const LESSONS=[];
CH.forEach(c=>c.ls.forEach((l,li)=>{l.id=c.id+'-'+li;l.ch=c;l.idx=li;LESSONS.push(l);}));
const TOTAL=LESSONS.length;

/* ---------- الحالة والحفظ ---------- */
const KEY='fiqh-maysar-v2';
const EXAM_N=10, PASS_PCT=80;
let mem=null;
function load(){
  try{const r=localStorage.getItem(KEY);if(r){const o=JSON.parse(r);if(o&&typeof o==='object')return Object.assign({name:'',lessons:{},days:[],exams:{}},o);}}catch(e){}
  return mem||{name:'',lessons:{},days:[],exams:{}};
}
let S=load();
if(!S.exams)S.exams={};
function save(){mem=S;try{localStorage.setItem(KEY,JSON.stringify(S));}catch(e){}}
const nf=new Intl.NumberFormat('ar-EG');
const n=x=>nf.format(x);
const pc=x=>n(Math.round(x))+'٪';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function dstr(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function streak(){
  const set=new Set(S.days);let d=new Date();
  if(!set.has(dstr(d)))d.setDate(d.getDate()-1);
  let c=0;while(set.has(dstr(d))){c++;d.setDate(d.getDate()-1);}
  return c;
}
function commit(){
  const set=new Set(S.days);const d=new Date();let c=0;
  for(let i=0;i<30;i++){if(set.has(dstr(d)))c++;d.setDate(d.getDate()-1);}
  return Math.round(c/30*100);
}
const rec=l=>S.lessons[l.id]||{best:0,done:false,attempts:0};
const exRec=c=>S.exams[c.id]||{best:0,attempts:0,passed:false};
const passMark=t=>Math.ceil(t*0.6);
const lessonsDone=c=>c.ls.filter(l=>rec(l).done).length;
const allLessons=c=>lessonsDone(c)===c.ls.length;
const chComplete=c=>allLessons(c)&&exRec(c).passed;
const chSteps=c=>c.ls.length+1;
const stepsDone=c=>lessonsDone(c)+(exRec(c).passed?1:0);
const secOf=k=>CH.filter(c=>c.sec===k);
const prevCh=c=>{const L=secOf(c.sec);const i=L.indexOf(c);return i>0?L[i-1]:null;};
const nextCh=c=>{const L=secOf(c.sec);const i=L.indexOf(c);return i<L.length-1?L[i+1]:null;};
const unlocked=c=>{const p=prevCh(c);return !p||chComplete(p);};
const doneCount=()=>LESSONS.filter(l=>rec(l).done).length;
function points(){
  const a=LESSONS.reduce((s,l)=>{const r=rec(l);return s+r.best*10+(r.done?20:0);},0);
  const b=CH.reduce((s,c)=>{const r=exRec(c);return s+(r.passed?50:0)+Math.round(r.best/10);},0);
  return a+b;
}
const MAXP=LESSONS.reduce((s,l)=>s+l.q.length*10+20,0)+CH.length*60;
const LEVELS=[[0,'مبتدئ'],[.1,'طالب علم'],[.3,'متعلّم متقدّم'],[.55,'متفقّه'],[.8,'متقن']].map(x=>[Math.round(x[0]*MAXP/10)*10,x[1]]);
function level(p){let i=0;LEVELS.forEach((l,k)=>{if(p>=l[0])i=k;});return i;}
function badges(){
  const b=[{ic:'star',t:'أول درس',d:'أنجز درسًا',on:doneCount()>=1,h:85},
           {ic:'check',t:'علامة كاملة',d:'أجب كل أسئلة اختبار صحيحة',on:LESSONS.some(l=>rec(l).best===l.q.length),h:160},
           {ic:'flame',t:'ثلاثة أيام',d:'تعلّم ٣ أيام متتالية',on:streak()>=3||(S.maxStreak||0)>=3,h:40}];
  CH.forEach(c=>b.push({ic:c.ic,t:c.t,d:'أنجز الباب باختباره',on:chComplete(c),h:c.h}));
  return b;
}
const TIPS=['قال النبي ﷺ: «من يُرد الله به خيرًا يفقّهه في الدين».','ابدأ بدرس واحد كل يوم، فالقليل الدائم خير من كثير منقطع.','راجع الباب قبل اختباره، فالمراجعة تثبّت المعلومة.','إذا اختلف العلماء في مسألة فارجع إلى عالم موثوق في بلدك.'];

